        'expires_at': expires_at,
        'username': user['username']
    }), 200

@app.route('/api/profile', methods=['GET'])
@require_session
def get_profile():
    db = get_db()
    user = db.execute(
        'SELECT id, username, display_name, email, created_at, is_admin FROM users WHERE id = ?',
        (g.current_user_id,)
    ).fetchone()
