@app.route('/api/profile', methods=['PUT'])
@require_session
def update_profile():
    data = request.get_json()
    if not data:
        return jsonify({'error': 'Invalid request body'}), 400

    db = get_db()
    allowed_fields = ['display_name', 'email']
    updates = {}

    for field in allowed_fields:
        if field in data:
            if field == 'email':
                valid, msg = validate_email(data[field])
                if not valid:
                    return jsonify({'error': msg}), 400
                updates[field] = data[field].lower()
            else:
                updates[field] = str(data[field])[:100]

    if not updates:
        return jsonify({'error': 'No valid fields to update'}), 400

    set_clause = ', '.join(f'{k} = ?' for k in updates.keys())
    values = list(updates.values()) + [g.current_user_id]
    db.execute(f'UPDATE users SET {set_clause} WHERE id = ?', values)
    db.commit()

    return jsonify({'message': 'Profile updated'}), 200

@app.route('/api/change-password', methods=['POST'])
@require_session
def change_password():
    data = request.get_json()
    if not data:
        return jsonify({'error': 'Invalid request body'}), 400

    current_password = data.get('current_password', '')
    new_password = data.get('new_password', '')

    if len(new_password) < 8:
        return jsonify({'error': 'New password must be at least 8 characters'}), 400

    db = get_db()
    user = db.execute(
        'SELECT * FROM users WHERE id = ?',
        (g.current_user_id,)
    ).fetchone()

    if not verify_password(current_password, user['password_hash']):
        return jsonify({'error': 'Current password is incorrect'}), 401

    new_hash = hash_password(new_password)
    db.execute(
        'UPDATE users SET password_hash = ? WHERE id = ?',
        (new_hash, g.current_user_id)
    )
    # Invalidate all other sessions
    db.execute(
        'DELETE FROM sessions WHERE user_id = ? AND token != ?',
        (g.current_user_id, request.headers.get('Authorization', '')[7:])
    )
    db.commit()

    return jsonify({'message': 'Password changed successfully'}), 200

