        'SELECT * FROM password_resets WHERE token = ? AND used = 0 AND created_at > ?',
        (token, time.time() - 3600)  # 1 hour expiry
    ).fetchone()

    if not reset:
        return jsonify({'error': 'Invalid or expired reset token'}), 400

    new_hash = hash_password(new_password)
    db.execute('UPDATE users SET password_hash = ? WHERE id = ?', (new_hash, reset['user_id']))
    db.execute('UPDATE password_resets SET used = 1 WHERE token = ?', (token,))
    db.execute('DELETE FROM sessions WHERE user_id = ?', (reset['user_id'],))
